def monedhat(shuma, m):
    dp = [0] + [float("inf")] * shuma
    for s in range(1, shuma + 1):
        dp[s] = min((dp[s - c] + 1 for c in m if c <= s), default=dp[s])
    return dp[shuma]

def bashko(iv):
    rez = []
    for a, b in sorted(iv):
        if rez and a <= rez[-1][1]: rez[-1][1] = max(rez[-1][1], b)
        else: rez.append([a, b])

