CREATE TABLE nxenesit (
  id SERIAL PRIMARY KEY,
  emri TEXT NOT NULL,
  nota INT CHECK (nota BETWEEN 1 AND 10)
);

SELECT emri, nota FROM nxenesit
ORDER BY nota DESC
LIMIT 3;

SELECT klasa, COUNT(*) AS nxenes, AVG(nota) AS mesatarja
FROM nxenesit
GROUP BY klasa;

SELECT klasa, AVG(nota) FROM nxenesit
GROUP BY klasa
HAVING AVG(nota) > 8;

SELECT n.emri, p.shuma
FROM nxenesit n
LEFT JOIN pagesat p ON p.nxenes_id = n.id;

SELECT emri FROM nxenesit
UNION
SELECT emri FROM mesuesit;

SELECT emri, klasa,
  RANK() OVER (PARTITION BY klasa ORDER BY nota DESC) AS vendi
FROM nxenesit;

CREATE TABLE nxenes_lende (
  nxenes_id INT REFERENCES nxenesit(id),
  lende_id INT REFERENCES lendet(id),
  PRIMARY KEY (nxenes_id, lende_id)
);

